import { EMPTY_OBJ, IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';
import { assign } from '../util';

/**
 * Set a property value on a DOM node
 * @param {PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture;
	let handler;
	let styleDecl;
	let styleName;
	let prevStyles;
	let nextStyles;
	let styleValue;
	let skipDomSet;

	function writeStyle(style, key, next) {
		let computed;
		if (key[0] === '-') {
			computed = next == null ? '' : next;
			style.setProperty(key, computed);
			return;
		}
		if (next == null) {
			style[key] = '';
			return;
		}
		if (typeof next != 'number') {
			style[key] = next;
			return;
		}
		if (IS_NON_DIMENSIONAL.test(key)) {
			style[key] = next;
			return;
		}
		style[key] = next + 'px';
	}

	function writeDomValue(propName, propValue) {
		skipDomSet = assign({}, EMPTY_OBJ);
		skipDomSet.width = 1;
		skipDomSet.height = 1;
		skipDomSet.href = 1;
		skipDomSet.list = 1;
		skipDomSet.form = 1;
		skipDomSet.tabIndex = 1;
		skipDomSet.download = 1;
		skipDomSet.rowSpan = 1;
		skipDomSet.colSpan = 1;
		skipDomSet.role = 1;

		if (isSvg) {
			// Normalize incorrect prop usage for SVG:
			// - xlink:href / xlinkHref --> href (xlink:href was removed from SVG and isn't needed)
			// - className --> class
			propName = propName.replace(/xlink(H|:h)/, 'h').replace(/sName$/, 's');
		} else if (skipDomSet[propName] !== 1 && propName in dom) {
			try {
				dom[propName] = propValue == null ? '' : propValue;
				return;
			} catch (e) {}
		}

		// aria- and data- attributes have no boolean representation.
		// A `false` value is different from the attribute not being
		// present, so we can't remove it. For non-boolean aria
		// attributes we could treat false as a removal, but the
		// amount of exceptions would cost too many bytes. On top of
		// that other frameworks generally stringify `false`.

		if (typeof propValue == 'function') {
			// never serialize functions as attribute values
			return;
		}
		if (propValue != null && (propValue !== false || propName[4] === '-')) {
			dom.setAttribute(propName, propValue);
			return;
		}
		dom.removeAttribute(propName);
	}

	if (name === 'style') {
		styleDecl = dom.style;
		if (typeof value == 'string') {
			styleDecl.cssText = value;
			return;
		}
		if (typeof oldValue == 'string') {
			styleDecl.cssText = oldValue = '';
		}

		prevStyles = oldValue || EMPTY_OBJ;
		nextStyles = value || EMPTY_OBJ;

		for (styleName in prevStyles) {
			if (!(value && styleName in nextStyles)) {
				writeStyle(styleDecl, styleName, '');
			}
		}

		for (styleName in nextStyles) {
			styleValue = nextStyles[styleName];
			if (!oldValue || styleValue !== prevStyles[styleName]) {
				writeStyle(styleDecl, styleName, styleValue);
			}
		}
		return;
	}
	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	if (name[0] === 'o' && name[1] === 'n') {
		useCapture =
			name !== (name = name.replace(/(PointerCapture)$|Capture$/i, '$1'));

		// Infer correct casing for DOM built-in events:
		if (name.toLowerCase() in dom) name = name.toLowerCase().slice(2);
		else name = name.slice(2);

		if (!dom._listeners) dom._listeners = {};
		dom._listeners[name + useCapture] = value;

		handler = eventProxy;
		if (useCapture) {
			handler = eventProxyCapture;
		}

		if (value) {
			if (!oldValue) {
				value._attached = Date.now();
				let listenerName = name;
				dom.addEventListener(listenerName, handler, useCapture);
			} else {
				value._attached = oldValue._attached;
			}
		} else {
			let listenerName = name;
			dom.removeEventListener(listenerName, handler, useCapture);
		}
		return;
	}

	writeDomValue(name, value);
}

/**
 * Proxy an event to hooked event handlers
 * @param {PreactEvent} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	if (this._listeners) {
		const eventHandler = this._listeners[e.type + false];
		/**
		 * This trick is inspired by Vue https://github.com/vuejs/core/blob/main/packages/runtime-dom/src/modules/events.ts#L90-L101
		 * when the dom performs an event it leaves micro-ticks in between bubbling up which means that an event can trigger on a newly
		 * created DOM-node while the event bubbles up, this can cause quirky behavior as seen in https://github.com/preactjs/preact/issues/3927
		 */
		if (!e._dispatched) {
			// When an event has no _dispatched we know this is the first event-target in the chain
			// so we set the initial dispatched time.
			e._dispatched = Date.now();
			// When the _dispatched is smaller than the time when the targetted event handler was attached
			// we know we have bubbled up to an element that was added during patching the dom.
		} else if (e._dispatched <= eventHandler._attached) {
			return;
		}
		return eventHandler(options.event ? options.event(e) : e);
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {PreactEvent} e The event object from the browser
 * @private
 */
function eventProxyCapture(e) {
	if (this._listeners) {
		return this._listeners[e.type + true](options.event ? options.event(e) : e);
	}
}

